import 'package:flutter/material.dart';

class SLoadingState extends StatelessWidget { const SLoadingState({super.key, this.label = 'Chargement…'}); final String label; @override Widget build(BuildContext context) => Center(child: Column(mainAxisSize: MainAxisSize.min, children: [const CircularProgressIndicator(color: Color(0xFFE90046)), const SizedBox(height: 12), Text(label)])); }
class SEmptyState extends StatelessWidget { const SEmptyState({super.key, required this.title, required this.message, this.action}); final String title, message; final Widget? action; @override Widget build(BuildContext context) => Center(child: Padding(padding: const EdgeInsets.all(24), child: Column(mainAxisSize: MainAxisSize.min, children: [const Icon(Icons.inbox_rounded, size: 40, color: Color(0xFF4A2630)), const SizedBox(height: 16), Text(title, style: Theme.of(context).textTheme.titleMedium), const SizedBox(height: 8), Text(message, textAlign: TextAlign.center), if (action != null) Padding(padding: const EdgeInsets.only(top: 16), child: action!)]))); }
class SErrorState extends StatelessWidget { const SErrorState({super.key, this.title = 'Une erreur est survenue', required this.onRetry}); final String title; final VoidCallback onRetry; @override Widget build(BuildContext context) => SEmptyState(title: title, message: 'Vérifie ta connexion puis réessaie.', action: FilledButton(onPressed: onRetry, child: const Text('Réessayer'))); }
class SToast { static void show(BuildContext context, String message, {bool error = false}) => ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(message), backgroundColor: error ? const Color(0xFF4A2630) : const Color(0xFFE90046), behavior: SnackBarBehavior.floating)); }
